class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)

    def update(self, pos, val, node=1, start=0, end=None):
        if end is None:
            end = self.n - 1
        if start == end:
            self.tree[node] += val
        else:
            mid = (start + end) // 2
            if pos <= mid:
                self.update(pos, val, 2 * node, start, mid)
            else:
                self.update(pos, val, 2 * node + 1, mid + 1, end)
            self.tree[node] = max(self.tree[2 * node], self.tree[2 * node + 1])

    def query(self, l, r, node=1, start=0, end=None):
        if end is None:
            end = self.n - 1
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        return max(self.query(l, r, 2 * node, start, mid), self.query(l, r, 2 * node + 1, mid + 1, end))

def solve(n: int, fogs: List[Tuple[int, int, int, int, int, int, int, int]]) -> int:
    max_x = 2 * 10**8
    segment_tree = SegmentTree(max_x)
    missed_fogs = 0

    for m, d, l, r, h, dd, dx, dh in fogs:
        for k in range(m):
            current_l = l + k * dx
            current_r = r + k * dx
            current_h = h + k * dh
            current_d = d + k * dd
            if current_d > 0:
                missed_fogs += current_h * (current_r - current_l) - segment_tree.query(current_l, current_r)
                segment_tree.update(current_l, current_h)
                segment_tree.update(current_r, -current_h)

    return missed_fogs

